// 【能坐过山车吗？】
// 先读入 n（0 到 100），再读入 n 个身高（50 到 250），都是整数。
// 输出 120 到 200 之间的身高，包含 120 和 200，每个数占一行。
// 例如输入（每个一行）：4、100 130 200 210
// 应该输出（每个一行）：130、200
// 提示：要同时满足两头，想想第 5 课的 &&。
// ↓ 在下面这段程序上改

#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;
    for (int i = 1; i <= n; i++) {
        int x = 0;
        cin >> x;
        if (x >= 60) {
            cout << x << endl;
        }
    }
    return 0;
}
